/**
 * Microsoft Outlook Node - Version 2
 * Discriminator: resource=folder, operation=update
 */


interface Credentials {
  microsoftOutlookOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Update a calendar */
export type MicrosoftOutlookV2FolderUpdateParams = {
  resource: 'folder';
  operation: 'update';
  authentication?: 'microsoftOutlookOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The mailbox the Service Principal should act on. In the action node this is evaluated per input item (an expression can target a different mailbox per item); the trigger resolves it once.
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"id","value":""}
 */
    mailbox?: { __rl: true; mode: 'id'; value: string; cachedResultName?: string };
/**
 * Folder
 * @searchListMethod searchFolders
 * @default {"mode":"list","value":""}
 */
    folderId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Name of the folder
 */
    displayName: string | Expression<string>;
};

export type MicrosoftOutlookV2FolderUpdateNode = {
  type: 'n8n-nodes-base.microsoftOutlook';
  version: 2;
  config: NodeConfig<MicrosoftOutlookV2FolderUpdateParams> & { credentials?: Credentials };
};